def newman_prime(n):
    def is_prime(num):
        if num < 2: return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0: return False
        return True
    count = 0
    a, b = 1, 7
    if is_prime(a):
        count += 1
        if count == n: return a
    if is_prime(b):
        count += 1
        if count == n: return b
    while True:
        c = 6 * b - a
        a, b = b, c
        if is_prime(b):
            count += 1
            if count == n: return b

def get_total_number_of_sequences(m,n): 
	T=[[0 for i in range(n+1)] for j in range(m+1)] 
	for i in range(m+1): 
		for j in range(n+1): 
			if i==0 or j==0: 
				T[i][j]=0
			elif j==1: 
				T[i][j]=i 
			else: 
				T[i][j]=T[i-1][j]+T[i//2][j-1] 
	return T[m][n]

